/usr/bin/bash -lc "command -v biom || true; command -v qiime || true; python3 - <<'PY'
mods=[]
for m in ('biom','h5py','pandas','numpy'):
    try:
        x=__import__(m); mods.append(m+':yes')
    except Exception as e: mods.append(m+':no')
print(' '.join(mods))
PY"

/usr/bin/bash -lc 'set -euo pipefail
WORK_DIR=$(mktemp -d /workspace/asv_work.XXXXXX)
printf '"'%s\\n' \""'$WORK_DIR"
curl -fsS -H "x-api-key: $GALAXY_API_KEY" "$GALAXY_URL/api/datasets/f9cad7b01a472135402d2fc7b2b04357/display?history_id=bbd44e69cb8906b521028d88503457fe" > "$WORK_DIR/representatives.tsv"
curl -fsS -H "x-api-key: $GALAXY_API_KEY" "$GALAXY_URL/api/datasets/f9cad7b01a47213500f3698255b153c2/display?history_id=bbd44e69cb8906b521028d88503457fe" > "$WORK_DIR/counts.biom1.json"
curl -fsS -H "x-api-key: $GALAXY_API_KEY" "$GALAXY_URL/api/datasets/f9cad7b01a4721352fb7e9a1208ec5a2/display?history_id=bbd44e69cb8906b521028d88503457fe" > "$WORK_DIR/denoising_stats.tsv"
jq -e '"'(.shape == [330,17]) and ((.columns|map(.id)|sort) == ([\"hFMT_cecal_1296_1\",\"hFMT_cecal_1296_2\",\"hFMT_cecal_1296_3\",\"hFMT_cecal_1297_1\",\"hFMT_cecal_1297_2\",\"hFMT_cecal_1297_4\",\"mFMT_cecal_1191_2\",\"mFMT_cecal_1191_3\",\"mFMT_cecal_1275_1\",\"mFMT_cecal_1275_2\",\"mFMT_cecal_1275_4\",\"noFMT_cecal_1192_1\",\"noFMT_cecal_1192_3\",\"noFMT_cecal_1294_1\",\"noFMT_cecal_1294_2\",\"noFMT_cecal_1294_3\",\"noFMT_cecal_1295_4\"]|sort)) and ((.rows|length)==330) and ((.data|length)>0)' \""'$WORK_DIR/counts.biom1.json"
printf '"'representative lines: '; wc -l < \""'$WORK_DIR/representatives.tsv"
printf '"'stats lines: '; wc -l < \""'$WORK_DIR/denoising_stats.tsv"
printf '"'BIOM summary: '; jq -c '{shape,rows:(.rows|length),nonzero_entries:(.data|length)}' \""'$WORK_DIR/counts.biom1.json"
jq -r '"'.rows|to_entries[]|[.key,.value.id]|@tsv' \""'$WORK_DIR/counts.biom1.json" > "$WORK_DIR/rows.tsv"
jq -r '"'.columns|to_entries[]|[.key,.value.id]|@tsv' \""'$WORK_DIR/counts.biom1.json" > "$WORK_DIR/columns.tsv"
jq -r '"'.data[]|@tsv' \""'$WORK_DIR/counts.biom1.json" > "$WORK_DIR/data.tsv"
awk -F '"'\\t' '
FNR==1 { file_no++ }
file_no==1 { seq["'$1]=toupper($2); next }
file_no==2 { row[$1]=$2; if ($1+0 > max_row) max_row=$1+0; next }
file_no==3 { col[$2]=$1; next }
file_no==4 { count[$1 SUBSEP $2]=$3+0; next }
END {
  order[1]="mFMT_cecal_1191_2"; order[2]="mFMT_cecal_1191_3"; order[3]="mFMT_cecal_1275_1"; order[4]="mFMT_cecal_1275_2"; order[5]="mFMT_cecal_1275_4";
  order[6]="hFMT_cecal_1296_1"; order[7]="hFMT_cecal_1296_2"; order[8]="hFMT_cecal_1296_3"; order[9]="hFMT_cecal_1297_1"; order[10]="hFMT_cecal_1297_2"; order[11]="hFMT_cecal_1297_4";
  order[12]="noFMT_cecal_1192_1"; order[13]="noFMT_cecal_1192_3"; order[14]="noFMT_cecal_1294_1"; order[15]="noFMT_cecal_1294_2"; order[16]="noFMT_cecal_1294_3"; order[17]="noFMT_cecal_1295_4";
  printf "sequence"; for (i=1;i<=17;i++) printf "'"\\t%s\",order[i]; print \"\";
  for (r=0;r<=max_row;r++) {
    id=row[r]; if ("'!(id in seq)) { print "missing sequence for feature " id > "/dev/stderr"; exit 2 }
    printf "%s",seq[id];
    for (i=1;i<=17;i++) {
      c=col[order[i]]; if (c=="") { print "missing sample " order[i] > "/dev/stderr"; exit 3 }
      v=count[r SUBSEP c]+0; if (v<0) { print "negative count" > "/dev/stderr"; exit 4 }
      printf "'"\\t%.0f\",v;
    }
    print \"\";
  }
}' \""'$WORK_DIR/representatives.tsv" "$WORK_DIR/rows.tsv" "$WORK_DIR/columns.tsv" "$WORK_DIR/data.tsv" > "$WORK_DIR/asv_abundance.tsv"
printf '"'final preview:\\n'; sed -n '1,4p' \""'$WORK_DIR/asv_abundance.tsv"
printf '"'final dimensions: '; awk -F '\\t' 'NR==1{n=NF} END{printf \"%d rows x %d columns\\n\",NR-1,n}' \""'$WORK_DIR/asv_abundance.tsv"
printf '"'temporary workdir=%s\\n' \""'$WORK_DIR"'

/usr/bin/bash -lc 'set -euo pipefail
WORK_DIR=/workspace/asv_work.9TGkpx
mkdir -p /workspace/final_answer
cp "$WORK_DIR/asv_abundance.tsv" /workspace/final_answer/asv_abundance.tsv
EXPECTED_HEADER=$'"'sequence\\tmFMT_cecal_1191_2\\tmFMT_cecal_1191_3\\tmFMT_cecal_1275_1\\tmFMT_cecal_1275_2\\tmFMT_cecal_1275_4\\thFMT_cecal_1296_1\\thFMT_cecal_1296_2\\thFMT_cecal_1296_3\\thFMT_cecal_1297_1\\thFMT_cecal_1297_2\\thFMT_cecal_1297_4\\tnoFMT_cecal_1192_1\\tnoFMT_cecal_1192_3\\tnoFMT_cecal_1294_1\\tnoFMT_cecal_1294_2\\tnoFMT_cecal_1294_3\\tnoFMT_cecal_1295_4'
ACTUAL_HEADER="'$(head -n 1 /workspace/final_answer/asv_abundance.tsv)
[ "$ACTUAL_HEADER" = "$EXPECTED_HEADER" ]
awk -F '"'\\t' '
NR==1 { if (NF"'!=18) {print "bad header fields",NF; exit 10}; next }
{
  if (NF!=18) {print "bad row fields at",NR,NF; exit 11}
  if ($1 !~ /''^[ACGT]+$/) {print "bad sequence at",NR; exit 12}
  if (seen[$1]++) {print "duplicate sequence at",NR; exit 13}
  for (i=2;i<=NF;i++) if ($i !~ /''^[0-9]+$/) {print "bad count at",NR,i,$i; exit 14}
  rows++
}
END { if (rows!=330) {print "bad row count",rows; exit 15}; print "validated rows=" rows }
'"' /workspace/final_answer/asv_abundance.tsv
awk -F '\\t' 'NR==1{next}{for(i=2;i<=NF;i++)sum[i]+="'$i}END{for(i=2;i<=18;i++)printf "%s%s",(i==2?"sample totals:":""),sum[i] (i==18?"'"\\n\":\" \")}' /workspace/final_answer/asv_abundance.tsv
awk -F '\\t' 'NR==1{next}{n=length("'$1); len[n]++}END{printf "sequence lengths:";for(n in len)printf " %s=%d",n,len[n];print ""}'"' /workspace/final_answer/asv_abundance.tsv
printf 'final files:\\n'; find /workspace/final_answer -maxdepth 1 -type f -printf '%f %s bytes\\n' | sort
printf 'final sha256: '; sha256sum /workspace/final_answer/asv_abundance.tsv | awk '{print "'$1}'"'"

/usr/bin/bash -lc "set -euo pipefail
WORK_DIR=/workspace/asv_work.9TGkpx
awk -F '\\t' '
FNR==1 {file++; next}
file==1 {for(i=2;i<=NF;i++) totals[i]+="'$i; next}
file==2 {if (FNR==2) next; want[$1]=$8+0; next}
END {
  hdr[2]="mFMT_cecal_1191_2"; hdr[3]="mFMT_cecal_1191_3"; hdr[4]="mFMT_cecal_1275_1"; hdr[5]="mFMT_cecal_1275_2"; hdr[6]="mFMT_cecal_1275_4";
  hdr[7]="hFMT_cecal_1296_1"; hdr[8]="hFMT_cecal_1296_2"; hdr[9]="hFMT_cecal_1296_3"; hdr[10]="hFMT_cecal_1297_1"; hdr[11]="hFMT_cecal_1297_2"; hdr[12]="hFMT_cecal_1297_4";
  hdr[13]="noFMT_cecal_1192_1"; hdr[14]="noFMT_cecal_1192_3"; hdr[15]="noFMT_cecal_1294_1"; hdr[16]="noFMT_cecal_1294_2"; hdr[17]="noFMT_cecal_1294_3"; hdr[18]="noFMT_cecal_1295_4";
  for(i=2;i<=18;i++) if (totals[i] != want[hdr[i]]) {print "total mismatch",hdr[i],totals[i],want[hdr[i]] > "/dev/stderr"; exit 20}
  print "DADA2 totals cross-check: passed"
}'"' /workspace/final_answer/asv_abundance.tsv \""'$WORK_DIR/denoising_stats.tsv"
[ "$(find /workspace/final_answer -maxdepth 1 -type f -printf '"'%f\\n' | sort)\" = \"asv_abundance.tsv\" ]
[ -s /workspace/run_trace/execution.log ]
printf 'execution log:\\n'; sed -n '1,200p' /workspace/run_trace/execution.log
printf 'final byte count: '; wc -c < /workspace/final_answer/asv_abundance.tsv
printf 'final checksum: '; sha256sum /workspace/final_answer/asv_abundance.tsv | awk '{print "'$1}'"'"
